/**
 * Anthropic Prompt Caching — 断点选择工具
 *
 * SSOT：缓存断点的选择逻辑集中在此文件。
 * anthropic-client.ts（原生 Anthropic）和 openai-client.ts（litellm 代理）
 * 共用断点选择算法，各自负责 cache_control 注入方式。
 */

/**
 * 选择 Anthropic prompt caching 断点位置 — SSOT 纯函数。
 *
 * 返回应设置 cache_control 的消息索引列表。
 *
 * Anthropic 最多支持 4 个缓存断点（ephemeral），激进策略全部用满：
 * 1. 最后一条 system 消息 — 缓存稳定的 system prompt
 * 2. 倒数第二个 **真实 user** 消息 — 稳定缓存锚点
 *    在 Anthropic 格式中 tool_result 也是 role=user，但它们每轮都在增长，
 *    不适合做锚点。真正的 user_input 消息才是稳定的对话边界。
 *    使用 isRealUser 回调来区分；未提供时退化为按 role=user 匹配（向后兼容）。
 * 3-4. 从末尾向前补满剩余 non-assistant 消息 — 最新历史缓存
 *
 * 当只有 1 个真实 user 消息时（无 reminder），断点 2 不存在，
 * 退化为 system + 最后 3 条 non-assistant（与旧策略等价）。
 */
export function selectCacheBreakpoints(
	messages: readonly { role: string }[],
	isRealUser?: (index: number) => boolean,
): number[] {
	const selected = new Set<number>();

	// 断点 1：最后一条 system 消息
	for (let i = messages.length - 1; i >= 0; i--) {
		if (messages[i]?.role === "system") {
			selected.add(i);
			break;
		}
	}

	// 断点 2：倒数第二个真实 user 消息（稳定缓存锚点）
	// isRealUser 区分 user_input（稳定）和 tool_result→user（每轮增长）
	const checkUser = isRealUser ?? ((i: number) => messages[i]?.role === "user");
	let realUserCount = 0;
	for (let i = messages.length - 1; i >= 0; i--) {
		if (checkUser(i)) {
			realUserCount++;
			if (realUserCount === 2) {
				selected.add(i);
				break;
			}
		}
	}

	// 断点 3-4（补满到 4 个）：从末尾向前取 non-assistant 消息，跳过已选中的
	for (let i = messages.length - 1; i >= 0 && selected.size < 4; i--) {
		if (selected.has(i)) continue;
		const role = messages[i]?.role;
		if (role === "user" || role === "tool") {
			selected.add(i);
		}
	}

	return [...selected];
}

/**
 * selectCacheBreakpoints 单元测试
 *
 * 验证 Anthropic prompt caching 断点选择策略：
 * - 始终选中最后一条 system 消息
 * - 有多个 user 消息时，倒数第二个 user 获得 anchor（thinking 清空后的稳定边界）
 * - 剩余配额从末尾向前取 non-assistant 消息
 * - 最多 4 个断点
 */

import { describe, expect, test } from "bun:test";
import { selectCacheBreakpoints } from "../cache.ts";

const S = { role: "system" };
const U = { role: "user" };
const A = { role: "assistant" };
const T = { role: "tool" };

describe("selectCacheBreakpoints", () => {
	test("最小序列: S U → system + user", () => {
		const bp = selectCacheBreakpoints([S, U]);
		expect(bp).toContain(0); // system
		expect(bp).toContain(1); // user
		expect(bp.length).toBe(2);
	});

	test("正常轮次(1 user, 3 tools): S U A T A T A T → system + 3 tools", () => {
		const msgs = [S, U, A, T, A, T, A, T];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp).toContain(0); // system
		// 应包含 user@1 和末尾的 tool，共 4 个
		expect(bp.length).toBe(4);
		expect(bp).toContain(7); // 最后一个 T
		expect(bp).toContain(5); // 倒数第二个 T
	});

	test("有 reminder(2 users): S U A T A T A T U → 倒数第二个 user 有 anchor", () => {
		const msgs = [S, U, A, T, A, T, A, T, U];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp).toContain(0); // system
		expect(bp).toContain(1); // 倒数第二个 user（关键！）
		expect(bp).toContain(8); // 最后一个 user (reminder)
		expect(bp).toContain(7); // 最后一个 tool
		expect(bp.length).toBe(4);
	});

	test("多个 reminder(3 users): S U A T U A T U → 倒数第二个 user 有 anchor", () => {
		const msgs = [S, U, A, T, U, A, T, U];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp).toContain(0); // system
		expect(bp).toContain(4); // 倒数第二个 user
		expect(bp).toContain(7); // 最后一个 user
		expect(bp.length).toBe(4);
	});

	test("长会话 + reminder: 确保 prev user 被选中", () => {
		const msgs = [S, U, A, T, A, T, A, T, A, T, A, T, U];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp).toContain(0); // system
		expect(bp).toContain(1); // 倒数第二个 user（prev user）
		expect(bp).toContain(12); // 最后一个 user (reminder)
		expect(bp).toContain(11); // 最后一个 tool
		expect(bp.length).toBe(4);
	});

	test("无 system 消息: 只选 non-assistant", () => {
		const msgs = [U, A, T, A, T];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp).not.toContain(-1);
		// 应选中 user@0, tool@2, tool@4
		expect(bp).toContain(0);
		expect(bp).toContain(4);
		expect(bp.length).toBeLessThanOrEqual(4);
	});

	test("最多 4 个断点", () => {
		// 很多 non-assistant 消息
		const msgs = [S, U, T, T, T, T, T, T, T, T];
		const bp = selectCacheBreakpoints(msgs);
		expect(bp.length).toBeLessThanOrEqual(4);
	});

	test("空消息列表", () => {
		const bp = selectCacheBreakpoints([]);
		expect(bp.length).toBe(0);
	});

	test("isRealUser: tool_result→user 不计入 anchor", () => {
		// S U A T(→user) A T(→user) A T(→user) U
		// 不传 isRealUser 时，倒数第二个 user 是 idx=5(tool)
		// 传 isRealUser 时，倒数第二个 real user 是 idx=0(user)
		const msgs = [S, U, A, U, A, U, A, U, U];
		// 没有 isRealUser: 倒数第二个 role=user 是 idx=7
		const bpOld = selectCacheBreakpoints(msgs);
		expect(bpOld).toContain(7); // 倒数第二个 user

		// 有 isRealUser: 只有 idx=1 和 idx=8 是 real user
		const realUsers = new Set([1, 8]);
		const bpNew = selectCacheBreakpoints(msgs, (i) => realUsers.has(i));
		expect(bpNew).toContain(1); // 倒数第二个 real user（anchor）
		expect(bpNew).toContain(8); // 最后一个 user
	});

	test("isRealUser: 未提供时退化为按 role=user 匹配", () => {
		const msgs = [S, U, A, T, U];
		const bp1 = selectCacheBreakpoints(msgs);
		const bp2 = selectCacheBreakpoints(msgs, undefined);
		expect(bp1).toEqual(bp2);
	});
});

/**
 * Prompt Caching 测试脚本
 * 
 * 通过 litellm gateway (OpenAI 兼容接口) 测试不同模型的 prompt caching 行为。
 * 
 * 测试方法：发送两次相同的长 system prompt 请求，观察第二次是否有 cache hit。
 * 
 * 用法: bun run scripts/test-caching.ts
 */

const BASE_URL = process.env.LLM_BASE_URL ?? "";
const API_KEY = process.env.LLM_API_KEY ?? "";

if (!API_KEY) {
	console.error("请设置 LLM_API_KEY 环境变量");
	process.exit(1);
}

if (!BASE_URL) {
	console.error("请设置 LLM_BASE_URL 环境变量");
	process.exit(1);
}

// 生成一个足够长的 system prompt（> 1024 tokens）以触发缓存
const LONG_SYSTEM_PROMPT = [
  "You are an expert software engineer assistant.",
  "You help with code reviews, debugging, and architecture decisions.",
  "You follow these principles:",
  ...Array.from({ length: 50 }, (_, i) => 
    `${i + 1}. Principle ${i + 1}: Always consider edge cases, error handling, performance implications, and maintainability when writing code. Use descriptive variable names, write comprehensive tests, and document your reasoning. Follow the DRY principle and SOLID design patterns. Consider backward compatibility and migration paths for any changes.`
  ),
  "Always respond concisely.",
].join("\n");

console.log(`System prompt length: ~${LONG_SYSTEM_PROMPT.length} chars`);

// 测试模型列表
const MODELS = [
  { name: "GPT-4o (OpenAI)", model: "gpt-4o" },
  { name: "Claude Sonnet 4.6", model: "claude-sonnet-4-6" },
  { name: "Gemini 2.5 Flash", model: "gemini-2.5-flash" },
];

interface UsageInfo {
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
  prompt_tokens_details?: {
    cached_tokens?: number;
    audio_tokens?: number;
  };
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  [key: string]: unknown;
}

async function sendRequest(
  model: string,
  extraHeaders?: Record<string, string>,
): Promise<{ text: string; usage: UsageInfo; rawHeaders: Record<string, string>; rawUsage: unknown }> {
  const messages = [
    { role: "system", content: LONG_SYSTEM_PROMPT },
    { role: "user", content: "What is 2+2? Answer in one word." },
  ];

  const res = await fetch(`${BASE_URL}/v1/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${API_KEY}`,
      ...extraHeaders,
    },
    body: JSON.stringify({
      model,
      messages,
      max_tokens: 10,
    }),
    signal: AbortSignal.timeout(30000),
  });

  // 收集响应头
  const rawHeaders: Record<string, string> = {};
  res.headers.forEach((v, k) => {
    if (/cache|token|usage|x-/i.test(k)) {
      rawHeaders[k] = v;
    }
  });

  const data = await res.json() as { choices: Array<{ message: { content: string } }>; usage: UsageInfo };
  return {
    text: data.choices?.[0]?.message?.content ?? "(no content)",
    usage: data.usage ?? {},
    rawHeaders,
    rawUsage: data.usage,
  };
}

async function testModel(config: { name: string; model: string }) {
  console.log(`\n${"=".repeat(60)}`);
  console.log(`Testing: ${config.name} (${config.model})`);
  console.log("=".repeat(60));

  try {
    // 第一次请求（cache write）
    console.log("\n--- Request 1 (cache write) ---");
    const r1 = await sendRequest(config.model);
    console.log(`  Response: ${r1.text}`);
    console.log(`  Usage: ${JSON.stringify(r1.rawUsage, null, 2)}`);
    if (Object.keys(r1.rawHeaders).length > 0) {
      console.log(`  Headers: ${JSON.stringify(r1.rawHeaders, null, 2)}`);
    }

    // 等 2 秒让缓存生效
    await new Promise(r => setTimeout(r, 2000));

    // 第二次请求（cache read）
    console.log("\n--- Request 2 (cache read) ---");
    const r2 = await sendRequest(config.model);
    console.log(`  Response: ${r2.text}`);
    console.log(`  Usage: ${JSON.stringify(r2.rawUsage, null, 2)}`);
    if (Object.keys(r2.rawHeaders).length > 0) {
      console.log(`  Headers: ${JSON.stringify(r2.rawHeaders, null, 2)}`);
    }

    // 分析缓存行为
    console.log("\n--- Cache Analysis ---");
    const u1 = r1.usage;
    const u2 = r2.usage;

    // OpenAI style: prompt_tokens_details.cached_tokens
    if (u2.prompt_tokens_details?.cached_tokens) {
      console.log(`  ✅ OpenAI cache hit: ${u2.prompt_tokens_details.cached_tokens} cached tokens (was ${u1.prompt_tokens_details?.cached_tokens ?? 0})`);
    }

    // Anthropic style: cache_creation_input_tokens / cache_read_input_tokens
    if (u1.cache_creation_input_tokens !== undefined || u2.cache_read_input_tokens !== undefined) {
      console.log(`  R1 cache_creation: ${u1.cache_creation_input_tokens ?? "N/A"}, cache_read: ${u1.cache_read_input_tokens ?? "N/A"}`);
      console.log(`  R2 cache_creation: ${u2.cache_creation_input_tokens ?? "N/A"}, cache_read: ${u2.cache_read_input_tokens ?? "N/A"}`);
      if ((u2.cache_read_input_tokens ?? 0) > 0) {
        console.log(`  ✅ Anthropic cache hit!`);
      }
    }

    // 对比 prompt tokens
    console.log(`  R1 prompt_tokens: ${u1.prompt_tokens}, R2 prompt_tokens: ${u2.prompt_tokens}`);

  } catch (err) {
    console.error(`  ❌ Error: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// 第二轮：测试 Anthropic 模型带 cache_control 标记
async function testAnthropicWithCacheControl() {
  console.log(`\n${"=".repeat(60)}`);
  console.log("Testing: Claude with explicit cache_control (litellm format)");
  console.log("=".repeat(60));

  const messages = [
    { 
      role: "system", 
      content: LONG_SYSTEM_PROMPT,
      // litellm 可能支持的 cache_control 格式
      cache_control: { type: "ephemeral" },
    },
    { role: "user", content: "What is 2+2? Answer in one word." },
  ];

  try {
    // 第一次
    console.log("\n--- Request 1 (with cache_control) ---");
    const res1 = await fetch(`${BASE_URL}/v1/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${API_KEY}`,
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        messages,
        max_tokens: 10,
      }),
      signal: AbortSignal.timeout(30000),
    });
    const d1 = await res1.json() as any;
    console.log(`  Usage: ${JSON.stringify(d1.usage, null, 2)}`);

    await new Promise(r => setTimeout(r, 2000));

    // 第二次
    console.log("\n--- Request 2 (with cache_control) ---");
    const res2 = await fetch(`${BASE_URL}/v1/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${API_KEY}`,
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        messages,
        max_tokens: 10,
      }),
      signal: AbortSignal.timeout(30000),
    });
    const d2 = await res2.json() as any;
    console.log(`  Usage: ${JSON.stringify(d2.usage, null, 2)}`);

    // 分析
    console.log("\n--- Cache Analysis ---");
    const u1 = d1.usage ?? {};
    const u2 = d2.usage ?? {};
    console.log(`  R1 cache_creation: ${u1.cache_creation_input_tokens ?? "N/A"}, cache_read: ${u1.cache_read_input_tokens ?? "N/A"}`);
    console.log(`  R2 cache_creation: ${u2.cache_creation_input_tokens ?? "N/A"}, cache_read: ${u2.cache_read_input_tokens ?? "N/A"}`);
  } catch (err) {
    console.error(`  ❌ Error: ${err instanceof Error ? err.message : String(err)}`);
  }
}

// 运行所有测试
for (const m of MODELS) {
  await testModel(m);
}

await testAnthropicWithCacheControl();

console.log("\n\nDone!");

