/**
 * 缓存锚点滑动行为测试
 *
 * 验证 selectCacheBreakpoints 在多轮对话增长过程中，
 * 断点3-4（末尾补充的 non-assistant 断点）是否每轮都在移动，
 * 导致 Anthropic prompt caching 前缀失效、产生不必要的 cache write 开销。
 *
 * Anthropic prompt caching 原理：
 * - cache_control 标记的位置决定缓存前缀的截止点
 * - 如果断点位置变化，即使内容不变，前缀也被视为不同，缓存失效
 * - cache write 的费用是 cache read 的 ~4 倍（Anthropic 定价）
 * - 因此频繁的断点滑动 = 频繁的 cache write = 不必要的开销
 */

import { describe, expect, test } from "bun:test";
import { selectCacheBreakpoints } from "../cache.ts";

const S = { role: "system" };
const U = { role: "user" };
const A = { role: "assistant" };
const T = { role: "tool" };

/**
 * 模拟一个典型的 agent 对话增长过程：
 * 用户发一条消息，agent 进行多轮 tool call。
 *
 * 对话模式: S U [A T]* (其中 [A T] 每轮增加一组)
 */
function buildConversation(toolRounds: number) {
	const msgs = [S, U];
	for (let i = 0; i < toolRounds; i++) {
		msgs.push(A, T);
	}
	return msgs;
}

/**
 * 模拟有 reminder 注入的对话（多个 real user 消息）：
 * S U [A T]* U_reminder [A T]*
 */
function buildConversationWithReminder(
	toolRoundsBefore: number,
	toolRoundsAfter: number,
) {
	const msgs = [S, U];
	for (let i = 0; i < toolRoundsBefore; i++) {
		msgs.push(A, T);
	}
	msgs.push(U); // reminder
	for (let i = 0; i < toolRoundsAfter; i++) {
		msgs.push(A, T);
	}
	return msgs;
}

describe("缓存锚点滑动分析", () => {
	test("无 reminder 场景：断点3-4随每轮 tool call 滑动", () => {
		const snapshots: { round: number; breakpoints: number[] }[] = [];

		// 模拟 10 轮 tool call
		for (let round = 1; round <= 10; round++) {
			const msgs = buildConversation(round);
			const bp = selectCacheBreakpoints(msgs);
			snapshots.push({ round, breakpoints: bp.sort((a, b) => a - b) });
		}

		// 统计断点在轮次间的变化
		let slidingCount = 0;
		for (let i = 1; i < snapshots.length; i++) {
			const prev = new Set(snapshots[i - 1]!.breakpoints);
			const curr = new Set(snapshots[i]!.breakpoints);

			// 不在上一轮中的新断点 = 滑动了
			const newBreakpoints = [...curr].filter((bp) => !prev.has(bp));
			// 上一轮有但本轮消失的断点 = 被替换了
			const removedBreakpoints = [...prev].filter((bp) => !curr.has(bp));

			if (newBreakpoints.length > 0 || removedBreakpoints.length > 0) {
				slidingCount++;
			}
		}

		// 输出详细的滑动情况
		console.log("\n=== 无 reminder 场景：断点滑动追踪 ===");
		console.log("轮次 | 消息数 | 断点位置");
		for (const s of snapshots) {
			const msgLen = 2 + s.round * 2;
			console.log(
