 * 对话模式: S U [A T]* (其中 [A T] 每轮增加一组)
 */
function buildConversation(toolRounds: number) {
	const msgs = [S, U];
	for (let i = 0; i < toolRounds; i++) {
		msgs.push(A, T);
	}
	return msgs;
}

