import { selectCacheBreakpoints } from "./packages/llm/src/cache.ts";

const S = { role: "system" };
const U = { role: "user" };
const A = { role: "assistant" };
const T = { role: "tool" };

// 模拟无 reminder 的对话增长
console.log("=== 详细分析：每轮断点变化 ===\n");
console.log("当前策略的问题：断点3-4每轮滑动，导致已缓存的前缀失效\n");

let prev = new Set<number>();
for (let round = 1; round <= 8; round++) {
    const msgs = [S, U, ...Array.from({length: round}, () => [A, T]).flat()];
    const bp = selectCacheBreakpoints(msgs).sort((a,b) => a-b);
    const bpSet = new Set(bp);

    const added = bp.filter(b => !prev.has(b));
    const removed = [...prev].filter(b => !bpSet.has(b));

    console.log(`轮次${round} (${msgs.length}条消息): 断点=[${bp.join(",")}]`);
    if (round > 1) {
        console.log(`  新增: [${added.join(",")}], 移除: [${removed.join(",")}]`);
        console.log(`  移除的断点意味着那个位置之前的缓存前缀白写了`);
    }
    prev = bpSet;
}

// 关键洞察：Anthropic cache 是前缀匹配
console.log("\n=== 核心问题：Anthropic 缓存前缀匹配 ===\n");
console.log("Anthropic 缓存的工作方式是：cache_control 标记处之前的所有内容作为前缀缓存。");
console.log("当 cache_control 标记的位置/内容改变时，前缀被认为不同，缓存失效。\n");

console.log("轮次3→4 的变化：");
console.log("  轮次3: 断点=[0,3,5,7] → 位置3的 tool msg 有 cache_control");
console.log("  轮次4: 断点=[0,5,7,9] → 位置3的 tool msg 失去 cache_control");
console.log("  → 位置3的消息内容未变，但 cache_control 标记被移除");
console.log("  → 从位置0到位置3的缓存前缀失效（因为格式变了）");
console.log("  → 需要重新 cache write 一个新前缀（0→5），cost = 3.75x");
console.log("");
console.log("如果只保持 system(0) + 尾部(最后1条)：");
console.log("  轮次3: 断点=[0,7]");
console.log("  轮次4: 断点=[0,9]");
console.log("  → system 缓存始终命中（cache read = 0.1x）");
console.log("  → 只有尾部1个断点在移动，cache write 最小化");

