import { selectCacheBreakpoints } from "./src/cache.ts";

const S = { role: "system" };
const U = { role: "user" };
const A = { role: "assistant" };
const T = { role: "tool" };

console.log("=== 详细分析：每轮断点变化 ===\n");

let prev = new Set<number>();
for (let round = 1; round <= 8; round++) {
    const msgs = [S, U, ...Array.from({length: round}, () => [A, T]).flat()];
    const bp = selectCacheBreakpoints(msgs).sort((a,b) => a-b);
    const bpSet = new Set(bp);

    const added = bp.filter(b => !prev.has(b));
    const removed = [...prev].filter(b => !bpSet.has(b));

    console.log(`轮次${round} (${msgs.length}条消息): 断点=[${bp.join(",")}]`);
    if (round > 1) {
        console.log(`  新增: [${added.join(",")}], 移除: [${removed.join(",")}]`);
    }
    prev = bpSet;
}

// 真正的问题量化：被移除的断点导致的缓存前缀失效
console.log("\n=== 核心量化：被移除断点导致的前缀重写 ===\n");

// 每个断点标记了一个缓存前缀终点。
// 当断点被移除时，之前该位置的缓存写入浪费了。
// 当断点被新增时（非尾部），该位置到前一断点之间的内容需要重新 cache write。
//
// 关键区别：
// - 2个断点（system + tail）：每轮只有 tail 移动，system 缓存永远命中
// - 4个断点（当前策略）：中间的断点每轮也在移动，每个移除+新增都是浪费

let totalRemoved = 0;
let totalAdded = 0;
prev = new Set<number>();

for (let round = 1; round <= 20; round++) {
    const msgs = [S, U, ...Array.from({length: round}, () => [A, T]).flat()];
    const bp = selectCacheBreakpoints(msgs).sort((a,b) => a-b);
    const bpSet = new Set(bp);

    if (round > 1) {
        for (const b of bpSet) if (!prev.has(b)) totalAdded++;
        for (const b of prev) if (!bpSet.has(b)) totalRemoved++;
    }
    prev = bpSet;
}

console.log(`20轮对话中：`);
console.log(`  断点新增次数: ${totalAdded} (每次 = 一笔 cache write)`);
console.log(`  断点移除次数: ${totalRemoved} (每次 = 之前的 cache write 浪费了)`);
console.log(`  浪费的 cache write: ${totalRemoved} 次`);

// 对比：2个断点策略
totalRemoved = 0;
totalAdded = 0;
prev = new Set<number>();

for (let round = 1; round <= 20; round++) {
    const msgs = [S, U, ...Array.from({length: round}, () => [A, T]).flat()];
    // 理想：只 system + 最后一条 non-assistant
    const ideal = [0];
    for (let i = msgs.length - 1; i >= 0; i--) {
        if (msgs[i]?.role !== "assistant" && msgs[i]?.role !== "system") {
            ideal.push(i);
            break;
        }
    }
    const bpSet = new Set(ideal);

    if (round > 1) {
        for (const b of bpSet) if (!prev.has(b)) totalAdded++;
        for (const b of prev) if (!bpSet.has(b)) totalRemoved++;
    }
    prev = bpSet;
}

console.log(`\n理想2断点策略（20轮）：`);
console.log(`  断点新增次数: ${totalAdded}`);
console.log(`  断点移除次数: ${totalRemoved}`);
console.log(`  浪费的 cache write: ${totalRemoved} 次`);

